package mathx

import (
	"bufio"
	"fmt"
	"os"
	"testing"
)

func TestAdd(t *testing.T) {
	f, err := os.Open("testdata/cases.txt")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	s := bufio.NewScanner(f)
	n := 0
	for s.Scan() {
		var a, b, want int
		if _, err := fmt.Sscan(s.Text(), &a, &b, &want); err != nil {
			t.Fatal(err)
		}
		if got := Add(a, b); got != want {
			t.Errorf("Add(%d,%d)=%d want %d", a, b, got, want)
		}
		n++
	}
	if n == 0 {
		t.Fatal("no cases")
	}
}

